180	  let cur: { title: string; lines: AIDiffLine[] } | null = null;
181	  for (const raw of patch.replace(/\n$/, "").split("\n")) {
182	    if (raw.startsWith("diff --git ")) {
183	      cur = { title: raw.replace(/^diff --git a\/(.*) b\/.*$/, "$1"), lines: [] };
