190	      cur.lines.push({ kind: "added", content: raw.slice(1) });
191	    } else if (raw.startsWith("-")) {
192	      cur.lines.push({ kind: "removed", content: raw.slice(1) });
193	    } else if (raw.length || cur.lines.length) {
